-- name: GetMap :one
SELECT m.id::text AS id, coalesce((select a.alias from map_aliases a where a.map_id=m.id order by a.created_at,a.alias limit 1),m.id::text) AS map_key, coalesce(m.owner_user_id::text,'')::text AS owner_user_id, case when m.official_at is not null then 'GeoDuels' else coalesce(u.display_name,'GeoDuels') end AS author_display_name, m.display_name, m.description, m.visibility, m.status, m.difficulty, m.thumbnail_variant, coalesce(m.thumbnail_key,'generic/variant-'||greatest(1,least(5,m.thumbnail_variant))::text) AS thumbnail_key, m.location_count, (m.owner_user_id is null or m.official_at is not null) AS is_system, m.official_at is not null AS is_official, coalesce(m.published_at,'0001-01-01'::timestamptz) AS published_at, m.play_count, m.favorite_count, m.comment_count, m.trending_score, exists(select 1 from map_favorites mf where mf.map_id=m.id and mf.user_id=nullif(sqlc.arg(viewer_user_id),'')::uuid) AS favorited, trim(both ':' from concat_ws(':',nullif(m.official_region_type,''),nullif(m.official_region_code,''))) AS official_region, exists(select 1 from map_aliases a where a.map_id=m.id and a.alias=coalesce((select value_json->>'movingMapId' from site_settings where key='gameplay_map_settings'),'moving')) AS mode_moving, exists(select 1 from map_aliases a where a.map_id=m.id and a.alias=coalesce((select value_json->>'noMoveMapId' from site_settings where key='gameplay_map_settings'),'nmpz')) AS mode_no_move, exists(select 1 from map_aliases a where a.map_id=m.id and a.alias=coalesce((select value_json->>'nmpzMapId' from site_settings where key='gameplay_map_settings'),'nmpz')) AS mode_nmpz, m.created_at, m.updated_at, pb.best_score, coalesce(pb.match_id::text,'') AS best_match_id, pb.achieved_at FROM maps m LEFT JOIN users u ON u.id=m.owner_user_id LEFT JOIN player_map_bests pb ON pb.map_id=m.id AND pb.user_id=nullif(sqlc.arg(viewer_user_id),'')::uuid AND pb.ruleset=0 WHERE (m.id::text=sqlc.arg(map_key) OR exists(select 1 from map_aliases a where a.map_id=m.id AND a.alias=sqlc.arg(map_key))) AND m.archived_at is null AND (m.owner_user_id is null OR m.official_at is not null OR m.owner_user_id=nullif(sqlc.arg(viewer_user_id),'')::uuid OR m.visibility in ('public','unlisted'));
-- name: ListMaps :many
SELECT m.id::text AS id, coalesce((select a.alias from map_aliases a where a.map_id=m.id order by a.created_at,a.alias limit 1),m.id::text) AS map_key, coalesce(m.owner_user_id::text,'')::text AS owner_user_id, case when m.official_at is not null then 'GeoDuels' else coalesce(u.display_name,'GeoDuels') end AS author_display_name, m.display_name, m.description, m.visibility, m.status, m.difficulty, m.thumbnail_variant, coalesce(m.thumbnail_key,'generic/variant-'||greatest(1,least(5,m.thumbnail_variant))::text) AS thumbnail_key, m.location_count, (m.owner_user_id is null or m.official_at is not null) AS is_system, m.official_at is not null AS is_official, coalesce(m.published_at,'0001-01-01'::timestamptz) AS published_at, m.play_count, m.favorite_count, m.comment_count, m.trending_score, exists(select 1 from map_favorites mf where mf.map_id=m.id and mf.user_id=nullif(sqlc.arg(viewer_user_id),'')::uuid) AS favorited, trim(both ':' from concat_ws(':',nullif(m.official_region_type,''),nullif(m.official_region_code,''))) AS official_region, exists(select 1 from map_aliases a where a.map_id=m.id and a.alias=coalesce((select value_json->>'movingMapId' from site_settings where key='gameplay_map_settings'),'moving')) AS mode_moving, exists(select 1 from map_aliases a where a.map_id=m.id and a.alias=coalesce((select value_json->>'noMoveMapId' from site_settings where key='gameplay_map_settings'),'nmpz')) AS mode_no_move, exists(select 1 from map_aliases a where a.map_id=m.id and a.alias=coalesce((select value_json->>'nmpzMapId' from site_settings where key='gameplay_map_settings'),'nmpz')) AS mode_nmpz, m.created_at, m.updated_at, pb.best_score, coalesce(pb.match_id::text,'') AS best_match_id, pb.achieved_at
FROM maps m LEFT JOIN users u ON u.id=m.owner_user_id LEFT JOIN player_map_bests pb ON pb.map_id=m.id AND pb.user_id=nullif(sqlc.arg(viewer_user_id),'')::uuid AND pb.ruleset=0
WHERE m.archived_at is null AND (sqlc.arg(scope)='all' OR (sqlc.arg(scope)='official' AND (m.owner_user_id is null OR m.official_at is not null)) OR (sqlc.arg(scope)='community' AND m.owner_user_id is not null AND m.visibility='public' AND m.status='ready') OR (sqlc.arg(scope)='favorites' AND exists(select 1 from map_favorites mf where mf.map_id=m.id and mf.user_id=nullif(sqlc.arg(viewer_user_id),'')::uuid)) OR (sqlc.arg(scope)='mine' AND m.owner_user_id=nullif(sqlc.arg(viewer_user_id),'')::uuid))
AND (sqlc.arg(search)='' OR m.display_name ilike sqlc.arg(search) escape '\\' OR m.description ilike sqlc.arg(search) escape '\\' OR exists(select 1 from map_aliases a where a.map_id=m.id and a.alias ilike sqlc.arg(search) escape '\\') OR coalesce(u.display_name,'GeoDuels') ilike sqlc.arg(search) escape '\\')
ORDER BY CASE WHEN sqlc.arg(sort)='popular' THEN (m.play_count+m.favorite_count*3) END DESC, CASE WHEN sqlc.arg(sort)='new' THEN m.published_at END DESC NULLS LAST, m.trending_score DESC, m.published_at DESC NULLS LAST, m.updated_at DESC LIMIT 72;
